def parse_duration(s):
    if not s:
        raise ValueError("Input string cannot be empty")

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total_seconds = 0
    prev_unit = None

    while s:
        for unit in units.keys():
            if s.endswith(unit):
                if prev_unit and units[unit] < units[prev_unit]:
                    raise ValueError("Units are out of order or repeated")
                prev_unit = unit
                num_str = s[:-len(unit)]
                if not num_str.isdigit():
                    raise ValueError(f"Invalid number before unit {unit}")
                num = int(num_str)
                total_seconds += num * units[unit]
                s = s[:-len(unit)]
                break
        else:
            raise ValueError(f"Unknown unit {s[-1]}")

    return total_seconds

