def wrap(text, width):
    if not text or text.isspace():
        return []

    words = text.split()
    lines = []
    current_line = ""

    for word in words:
        if (len(current_line) + len(word)) <= width:
            if current_line:
                current_line += " " + word
            else:
                current_line += word
        else:
            lines.append(current_line)
            current_line = word

    lines.append(current_line)
    return lines

# Example usage:
text = "The quick brown fox jumps over the lazy dog"
width = 15
print(wrap(text, width))
