import heapq

def shortest(graph, start, goal):
    if start == goal:
        return (0, [start])

    # Priority queue to store the nodes to be processed
    queue = [(0, start, [])]
    visited = set()

    while queue:
        (cost, node, path) = heapq.heappop(queue)
        if node not in visited:
            visited.add(node)
            path = path + [node]
            if node == goal:
                return (cost, path)

            for (neighbour, weight) in graph[node]:
                if neighbour not in visited:
                    heapq.heappush(queue, (cost + weight, neighbour, path))

    return (None, [])

