from collections import deque, defaultdict

def shortest(graph, start, goal):
    if start == goal:
        return (0, [start])

    # Initialize the distance and path dictionaries
    dist = {start: 0}
    prev = {}
    queue = deque([start])

    while queue:
        current = queue.popleft()
        if current == goal:
            break

        for neighbor, weight in graph[current]:
            alt = dist.get(current, float('inf')) + weight
            if neighbor not in dist or alt < dist[neighbor]:
                dist[neighbor] = alt
                prev[neighbor] = current
                queue.append(neighbor)

    if goal not in dist:
        return (None, [])

    # Reconstruct the path
    path = []
    while goal in prev:
        path.append(goal)
        goal = prev[goal]
    path.append(start)
    path.reverse()

    return (dist[path[-1]], path)

