from collections import defaultdict
import heapq

def shortest(graph, start, goal):
    if start == goal:
        return (0, [start])

    # Priority queue for Dijkstra's algorithm
    queue = [(0, start)]
    visited = set()
    previous = {node: [] for node in graph}
    distance = {node: float('inf') for node in graph}
    distance[start] = 0

    while queue:
        current_distance, node = heapq.heappop(queue)

        if node in visited:
            continue

        visited.add(node)

        if node == goal:
            break

        for neighbor, weight in graph[node]:
            if distance.get(neighbor) is None:
                distance[neighbor] = float('inf')
            if distance[neighbor] > current_distance + weight:
                distance[neighbor] = current_distance + weight
                previous[neighbor] = node
                heapq.heappush(queue, (distance[neighbor], neighbor))

    if distance[goal] == float('inf'):
        return (None, [])

    # Reconstruct the path
    path = []
    current = goal
    while current != start:
        path.insert(0, current)
        current = previous[current]
    path.insert(0, start)

    return (distance[goal], path)
