def spiral(matrix):
    result = []
    while matrix:
        # Pop the first row and extend it to result
        result.extend(matrix.pop(0))

        if matrix and matrix[0]:
            # Pop elements from the end of the first column and prepend them to maintain clockwise order
            for row in matrix[:-1]:
                result.append(row.pop())

        if matrix:
            # Pop the last row in reverse order and extend it to result
            result.extend(matrix.pop()[::-1])

        if matrix and matrix[0]:
            # Pop elements from the end of the last column and prepend them to maintain clockwise order
            for row in matrix[::-1]:
                result.append(row.pop(0))

    return result

